{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.hit_rate_sku_group_DOD as WITH meta_map AS ( SELECT UPPER(IFF( UPPER(REPLACE(SKU_GROUP,\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP,\' \',\'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',1)||\'-\'||SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',2), SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',1) )) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), all_sales AS ( SELECT date, sku_group, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1,2 UNION ALL SELECT TO_DATE(order_created_date,\'YYYYMMDD\'), style_, SUM(TRY_TO_NUMBER(REPLACE(sales,\',\',\'\'))) FROM snitch_db.maplemonk.mp_sor_sales_myntra GROUP BY 1,2 UNION ALL SELECT TO_DATE(order_date_key,\'YYYYMMDD\'), style_, SUM(TRY_TO_NUMBER(REPLACE(units,\',\',\'\'))) FROM snitch_db.maplemonk.mp_sor_sales_flipkart GROUP BY 1,2 ), daily_sales AS ( SELECT date, sku_group, SUM(qty) AS daily_qty FROM all_sales GROUP BY 1,2 ), raw_inwards AS ( SELECT UPPER(TRIM(REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\',REVERSE(\"Item Type skuCode\"))+1, LEN(\"Item Type skuCode\") )))) AS sku_group, \"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking GROUP BY 1,2 HAVING SUM(\"PUTAWAY_COMPLETED_QUANTITY\") >= 100 ), inward_with_gap AS ( SELECT sku_group, inward_date, inward_qty, LAG(inward_date) OVER (PARTITION BY sku_group ORDER BY inward_date) AS prev_inward_date, DATEDIFF(\'day\', LAG(inward_date) OVER (PARTITION BY sku_group ORDER BY inward_date), inward_date) AS days_since_prev FROM raw_inwards ), inward_batch_flag AS ( SELECT sku_group, inward_date, inward_qty, CASE WHEN prev_inward_date IS NULL THEN 1 WHEN days_since_prev >= 60 THEN 1 ELSE 0 END AS is_new_batch FROM inward_with_gap ), inward_batches_raw AS ( SELECT sku_group, inward_date, inward_qty, SUM(is_new_batch) OVER (PARTITION BY sku_group ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS batch_number FROM inward_batch_flag ), inward_batches AS ( SELECT sku_group, batch_number, MIN(inward_date) AS batch_inward_date, SUM(inward_qty) AS batch_inward_qty FROM inward_batches_raw GROUP BY 1,2 ), sku_noos_flag AS ( SELECT sku_group, COUNT(DISTINCT batch_number) AS total_batches, MIN(batch_inward_date) AS first_inward_date, CASE WHEN COUNT(DISTINCT batch_number) >= 2 THEN 1 ELSE 0 END AS is_noos FROM inward_batches GROUP BY 1 ), inward_batches_windowed AS ( SELECT ib.sku_group, ib.batch_number, ib.batch_inward_date, ib.batch_inward_qty, COALESCE(DATEADD(\'day\',-1, LEAD(ib.batch_inward_date) OVER (PARTITION BY ib.sku_group ORDER BY ib.batch_number) ), CURRENT_DATE()) AS batch_window_end FROM inward_batches ib ), batch_sales_all AS ( SELECT ibw.sku_group, ibw.batch_number, ibw.batch_inward_date, ibw.batch_inward_qty, ibw.batch_window_end, ds2.date AS sale_date, ds2.daily_qty, SUM(ds2.daily_qty) OVER ( PARTITION BY ibw.sku_group, ibw.batch_number ORDER BY ds2.date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_sales_in_window FROM inward_batches_windowed ibw JOIN (SELECT date, sku_group, SUM(gross_quantity::INT) AS daily_qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1,2) ds2 ON ds2.sku_group = ibw.sku_group AND ds2.date BETWEEN ibw.batch_inward_date AND ibw.batch_window_end ), batch_milestones_all AS ( SELECT sku_group, batch_number, batch_inward_date, batch_inward_qty, batch_window_end, MIN(CASE WHEN cum_sales_in_window >= batch_inward_qty*0.30 THEN DATEDIFF(\'day\',batch_inward_date,sale_date) END) AS days_to_30pct, MIN(CASE WHEN cum_sales_in_window >= batch_inward_qty*0.60 THEN DATEDIFF(\'day\',batch_inward_date,sale_date) END) AS days_to_60pct, MIN(CASE WHEN cum_sales_in_window >= batch_inward_qty*0.90 THEN DATEDIFF(\'day\',batch_inward_date,sale_date) END) AS days_to_90pct FROM batch_sales_all GROUP BY 1,2,3,4,5 ), sku_categories AS ( SELECT DISTINCT bm.sku_group, mm.l1_category, mm.category FROM batch_milestones_all bm LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER(IFF( UPPER(REPLACE(bm.sku_group,\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(bm.sku_group,\' \',\'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(bm.sku_group,\' \',\'\'),\'-\',1)||\'-\'||SPLIT_PART(REPLACE(bm.sku_group,\' \',\'\'),\'-\',2), SPLIT_PART(REPLACE(bm.sku_group,\' \',\'\'),\'-\',1) )) ), all_batch_milestones AS ( SELECT UPPER(TRIM(REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\',REVERSE(\"Item Type skuCode\"))+1, LEN(\"Item Type skuCode\") )))) AS sku_group, \"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) = \'new inward\' GROUP BY 1,2 HAVING SUM(\"PUTAWAY_COMPLETED_QUANTITY\") >= 100 ), category_benchmarks AS ( SELECT l1_category, category, ROUND(AVG(avg_days_to_30pct),1) AS avg_days_to_30pct, ROUND(AVG(avg_days_to_60pct),1) AS avg_days_to_60pct, ROUND(AVG(avg_days_to_90pct),1) AS avg_days_to_90pct FROM snitch_db.maplemonk.hit_product_info_inv WHERE avg_days_to_90pct IS NOT NULL GROUP BY 1,2 ), date_spine AS ( SELECT DATEADD(\'day\', ROW_NUMBER() OVER (ORDER BY SEQ4()) - 1, (SELECT MIN(batch_inward_date) FROM inward_batches) ) AS date FROM TABLE(GENERATOR(ROWCOUNT => 2000)) QUALIFY date <= CURRENT_DATE() ), sku_date_spine AS ( SELECT ds.date, nf.sku_group FROM date_spine ds JOIN sku_noos_flag nf ON ds.date >= nf.first_inward_date ), latest_batch_per_date AS ( SELECT sds.date, sds.sku_group, MAX(ib.batch_number) AS latest_batch_number FROM sku_date_spine sds JOIN inward_batches ib ON ib.sku_group = sds.sku_group AND ib.batch_inward_date <= sds.date GROUP BY 1,2 ), active_batch_per_date AS ( SELECT lb.date, lb.sku_group, lb.latest_batch_number AS batch_number, ib.batch_inward_date, ib.batch_inward_qty, ibw.batch_window_end FROM latest_batch_per_date lb JOIN inward_batches ib ON ib.sku_group=lb.sku_group AND ib.batch_number=lb.latest_batch_number JOIN inward_batches_windowed ibw ON ibw.sku_group=lb.sku_group AND ibw.batch_number=lb.latest_batch_number ), dod_cum_sales AS ( SELECT ab.date, ab.sku_group, ab.batch_number, ab.batch_inward_date, ab.batch_inward_qty, ab.batch_window_end, DATEDIFF(\'day\', ab.batch_inward_date, ab.date) AS days_since_inward, COALESCE(SUM(ds.daily_qty), 0) AS cum_sales_to_date FROM active_batch_per_date ab LEFT JOIN daily_sales ds ON ds.sku_group = ab.sku_group AND ds.date BETWEEN ab.batch_inward_date AND ab.date AND ds.date <= ab.batch_window_end GROUP BY 1,2,3,4,5,6,7 ), dod_milestones AS ( SELECT *, ROUND(cum_sales_to_date / NULLIF(batch_inward_qty,0)*100,2) AS sell_through_pct, CASE WHEN cum_sales_to_date >= batch_inward_qty*0.30 THEN days_since_inward ELSE NULL END AS days_to_30pct_raw, CASE WHEN cum_sales_to_date >= batch_inward_qty*0.60 THEN days_since_inward ELSE NULL END AS days_to_60pct_raw, CASE WHEN cum_sales_to_date >= batch_inward_qty*0.90 THEN days_since_inward ELSE NULL END AS days_to_90pct_raw FROM dod_cum_sales ), dod_milestones_final AS ( SELECT *, MIN(days_to_30pct_raw) OVER (PARTITION BY sku_group,batch_number ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS days_to_30pct, MIN(days_to_60pct_raw) OVER (PARTITION BY sku_group,batch_number ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS days_to_60pct, MIN(days_to_90pct_raw) OVER (PARTITION BY sku_group,batch_number ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS days_to_90pct FROM dod_milestones ) SELECT dm.date, dm.sku_group, sc.l1_category, sc.category, nf.is_noos, dm.batch_number, dm.batch_inward_date, dm.batch_inward_qty, dm.days_since_inward, dm.cum_sales_to_date, dm.sell_through_pct, dm.days_to_30pct, dm.days_to_60pct, dm.days_to_90pct, cb.avg_days_to_30pct, cb.avg_days_to_60pct, cb.avg_days_to_90pct, CASE WHEN dm.days_to_30pct IS NOT NULL AND dm.days_to_30pct <= cb.avg_days_to_30pct THEN \'yes\' ELSE \'No\' END AS beat_30pct, CASE WHEN dm.days_to_60pct IS NOT NULL AND dm.days_to_60pct <= cb.avg_days_to_60pct THEN \'yes\' ELSE \'No\' END AS beat_60pct, CASE WHEN dm.days_to_90pct IS NOT NULL AND dm.days_to_90pct <= cb.avg_days_to_90pct THEN \'yes\' ELSE \'No\' END AS beat_90pct, (CASE WHEN dm.days_to_30pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN dm.days_to_60pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN dm.days_to_90pct IS NOT NULL THEN 1 ELSE 0 END) AS metrics_available, (CASE WHEN dm.days_to_30pct IS NOT NULL AND dm.days_to_30pct <= cb.avg_days_to_30pct THEN 1 ELSE 0 END + CASE WHEN dm.days_to_60pct IS NOT NULL AND dm.days_to_60pct <= cb.avg_days_to_60pct THEN 1 ELSE 0 END + CASE WHEN dm.days_to_90pct IS NOT NULL AND dm.days_to_90pct <= cb.avg_days_to_90pct THEN 1 ELSE 0 END) AS metrics_beating, CASE WHEN nf.is_noos = 1 THEN \'NOOS\' WHEN (CASE WHEN dm.days_to_30pct IS NOT NULL AND dm.days_to_30pct <= cb.avg_days_to_30pct THEN 1 ELSE 0 END + CASE WHEN dm.days_to_60pct IS NOT NULL AND dm.days_to_60pct <= cb.avg_days_to_60pct THEN 1 ELSE 0 END + CASE WHEN dm.days_to_90pct IS NOT NULL AND dm.days_to_90pct <= cb.avg_days_to_90pct THEN 1 ELSE 0 END) >= 2 THEN \'Hit\' WHEN (CASE WHEN dm.days_to_30pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN dm.days_to_60pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN dm.days_to_90pct IS NOT NULL THEN 1 ELSE 0 END) = 1 AND (CASE WHEN dm.days_to_30pct IS NOT NULL AND dm.days_to_30pct <= cb.avg_days_to_30pct THEN 1 ELSE 0 END + CASE WHEN dm.days_to_60pct IS NOT NULL AND dm.days_to_60pct <= cb.avg_days_to_60pct THEN 1 ELSE 0 END + CASE WHEN dm.days_to_90pct IS NOT NULL AND dm.days_to_90pct <= cb.avg_days_to_90pct THEN 1 ELSE 0 END) = 1 THEN \'Hit\' WHEN (CASE WHEN dm.days_to_30pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN dm.days_to_60pct IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN dm.days_to_90pct IS NOT NULL THEN 1 ELSE 0 END) = 0 THEN \'New\' ELSE \'Not a Hit\' END AS hit_label_dod FROM dod_milestones_final dm JOIN sku_categories sc ON dm.sku_group = sc.sku_group JOIN sku_noos_flag nf ON dm.sku_group = nf.sku_group LEFT JOIN category_benchmarks cb ON sc.l1_category = cb.l1_category AND sc.category = cb.category where dm.sku_group=\'4SFS013-07\' ORDER BY dm.sku_group, dm.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            